func (q *Queries) TouchRunningJob(ctx context.Context, arg TouchRunningJobParams) (int64, error) {
	result, err := q.db.Exec(ctx, touchRunningJob, arg.ID, arg.Attempt)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateJobProgress = `-- name: UpdateJobProgress :one
UPDATE jobs
SET progress = $3, updated_at = now()
WHERE id = $1 AND status = 'running' AND attempt = $2
RETURNING id, project_id, asset_id, clip_id, stage, status, progress, attempt, max_attempts, next_attempt_at, idempotency_key, error_code, error_message, ai_input_tokens, ai_output_tokens, ai_cost_usd, prompt_version, model, created_at, updated_at, started_at, finished_at
`

type UpdateJobProgressParams struct {
	ID       string
	Attempt  int32
	Progress *float32
}

func (q *Queries) UpdateJobProgress(ctx context.Context, arg UpdateJobProgressParams) (Job, error) {
	row := q.db.QueryRow(ctx, updateJobProgress, arg.ID, arg.Attempt, arg.Progress)
	var i Job
	err := row.Scan(
		&i.ID,
		&i.ProjectID,
		&i.AssetID,
		&i.ClipID,
		&i.Stage,
		&i.Status,
		&i.Progress,
		&i.Attempt,
		&i.MaxAttempts,
		&i.NextAttemptAt,
		&i.IdempotencyKey,
		&i.ErrorCode,
		&i.ErrorMessage,
		&i.AiInputTokens,
		&i.AiOutputTokens,
		&i.AiCostUsd,
		&i.PromptVersion,
		&i.Model,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.StartedAt,
		&i.FinishedAt,
	)
	return i, err
}
